<?php
declare(strict_types=1);namespace App\Modules\SupplierPayments\Repositories;use App\Core\Database\Database;use App\Modules\SupplierPayments\DTOs\SupplierPaymentData;use App\Modules\SupplierPayments\DTOs\SupplierPaymentTableQuery;final class SupplierPaymentRepository{public function __construct(private readonly Database$db){}private function one(string$sql,array$p=[]):?array{$r=$this->db->execute($sql,$p);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}
public function invoice(int$id,bool$lock=false):?array{return$this->one("SELECT i.*,v.vendor_code,v.name vendor_name,p.project_code,p.name project_name FROM supplier_invoices i JOIN vendors v ON v.id=i.vendor_id JOIN projects p ON p.id=i.project_id WHERE i.id=?".($lock?' FOR UPDATE':''),[$id]);}public function find(int$id,bool$lock=false):?array{return$this->one("SELECT py.*,i.invoice_code,i.invoice_number,i.total_amount invoice_total,v.name vendor_name,p.name project_name,cu.name created_by_name,pu.name posted_by_name,xu.name cancelled_by_name FROM supplier_payments py JOIN supplier_invoices i ON i.id=py.supplier_invoice_id JOIN vendors v ON v.id=py.vendor_id JOIN projects p ON p.id=py.project_id JOIN users cu ON cu.id=py.created_by LEFT JOIN users pu ON pu.id=py.posted_by LEFT JOIN users xu ON xu.id=py.cancelled_by WHERE py.id=?".($lock?' FOR UPDATE':''),[$id]);}public function findForInvoice(int$id,int$invoiceId,bool$lock=false):?array{return$this->one("SELECT py.*,i.invoice_code,i.invoice_number,i.total_amount invoice_total,v.name vendor_name,p.name project_name,cu.name created_by_name,pu.name posted_by_name,xu.name cancelled_by_name FROM supplier_payments py JOIN supplier_invoices i ON i.id=py.supplier_invoice_id JOIN vendors v ON v.id=py.vendor_id JOIN projects p ON p.id=py.project_id JOIN users cu ON cu.id=py.created_by LEFT JOIN users pu ON pu.id=py.posted_by LEFT JOIN users xu ON xu.id=py.cancelled_by WHERE py.id=? AND py.supplier_invoice_id=?".($lock?' FOR UPDATE':''),[$id,$invoiceId]);}
public function create(string$code,SupplierPaymentData$d,array$i,int$user):int{$this->db->execute("INSERT INTO supplier_payments(payment_code,supplier_invoice_id,vendor_id,project_id,payment_date,amount,payment_method,reference,notes,status,created_by)VALUES(?,?,?,?,?,?,?,?,?,'draft',?)",[$code,$d->supplierInvoiceId,$i['vendor_id'],$i['project_id'],$d->paymentDate,$d->amount,$d->paymentMethod,$d->reference,$d->notes,$user]);return(int)$this->db->connection()->insert_id;}public function update(int$id,SupplierPaymentData$d):void{$this->db->execute("UPDATE supplier_payments SET payment_date=?,amount=?,payment_method=?,reference=?,notes=? WHERE id=? AND status='draft'",[$d->paymentDate,$d->amount,$d->paymentMethod,$d->reference,$d->notes,$id]);}public function postedTotal(int$id):string{return(string)($this->one("SELECT CAST(COALESCE(SUM(amount),0) AS DECIMAL(18,2)) total FROM supplier_payments WHERE supplier_invoice_id=? AND status='posted'",[$id])['total']??'0.00');}public function payable(string$total,string$paid):array{return$this->one('SELECT CAST(? AS DECIMAL(18,2)) invoice_total,CAST(? AS DECIMAL(18,2)) paid,CAST(?-? AS DECIMAL(18,2)) remaining',[$total,$paid,$total,$paid])??[];}public function exceeds(string$a,string$b):bool{return(int)($this->one('SELECT CAST(? AS DECIMAL(18,2))>CAST(? AS DECIMAL(18,2)) x',[$a,$b])['x']??1)===1;}
public function post(int$id,int$user,array$i,string$paid,string$remaining):void{$this->db->execute("UPDATE supplier_payments SET invoice_code_snapshot=?,invoice_number_snapshot=?,vendor_code_snapshot=?,vendor_name_snapshot=?,project_code_snapshot=?,project_name_snapshot=?,invoice_total_snapshot=?,previous_paid_snapshot=?,remaining_payable_snapshot=?,status='posted',posted_at=NOW(),posted_by=? WHERE id=? AND status='draft'",[$i['invoice_code'],$i['invoice_number'],$i['vendor_code'],$i['vendor_name'],$i['project_code'],$i['project_name'],$i['total_amount'],$paid,$remaining,$user,$id]);}public function cancel(int$id,int$user):void{$this->db->execute("UPDATE supplier_payments SET status='cancelled',cancelled_at=NOW(),cancelled_by=? WHERE id=? AND status='draft'",[$user,$id]);}
public function references():array{return['invoices'=>$this->rows("SELECT i.id,i.invoice_code,i.invoice_number,i.total_amount,v.name vendor_name,p.name project_name FROM supplier_invoices i JOIN vendors v ON v.id=i.vendor_id JOIN projects p ON p.id=i.project_id WHERE i.status='approved' ORDER BY i.invoice_date DESC,i.id DESC"),'vendors'=>$this->rows('SELECT id,name FROM vendors ORDER BY name'),'projects'=>$this->rows('SELECT id,name FROM projects ORDER BY name')];}private function rows(string$sql,array$p=[]):array{$r=$this->db->execute($sql,$p);return$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}
public function historicalIdentity(int$id):?array{return$this->one("SELECT invoice_code_snapshot invoice_code,invoice_number_snapshot invoice_number,vendor_code_snapshot vendor_code,vendor_name_snapshot vendor_name,project_code_snapshot project_code,project_name_snapshot project_name,invoice_total_snapshot invoice_total FROM supplier_payments WHERE id=? AND status='posted'",[$id]);}
public function historicalIdentities(array$ids):array{if($ids===[])return[];$q=implode(',',array_fill(0,count($ids),'?'));$rows=$this->rows("SELECT id,invoice_code_snapshot invoice_code,invoice_number_snapshot invoice_number,vendor_name_snapshot vendor_name,project_name_snapshot project_name FROM supplier_payments WHERE status='posted' AND id IN($q)",$ids);return array_column($rows,null,'id');}
public function dataTable(SupplierPaymentTableQuery$q):array{$w=[];$p=[];foreach(['py.supplier_invoice_id'=>$q->invoiceId,'py.vendor_id'=>$q->vendorId,'py.project_id'=>$q->projectId,'py.status'=>$q->status,'py.payment_method'=>$q->method]as$f=>$v)if($v!==null){$w[]="$f=?";$p[]=$v;}if($q->dateFrom){$w[]='py.payment_date>=?';$p[]=$q->dateFrom;}if($q->dateTo){$w[]='py.payment_date<=?';$p[]=$q->dateTo;}if($q->search!==''){$s='%'.$q->search.'%';$w[]='(py.payment_code LIKE ? OR i.invoice_code LIKE ? OR i.invoice_number LIKE ? OR v.name LIKE ? OR p.name LIKE ?)';array_push($p,$s,$s,$s,$s,$s);}$where=$w?' WHERE '.implode(' AND ',$w):'';$from=' FROM supplier_payments py JOIN supplier_invoices i ON i.id=py.supplier_invoice_id JOIN vendors v ON v.id=py.vendor_id JOIN projects p ON p.id=py.project_id';$total=$this->one('SELECT COUNT(*) total FROM supplier_payments');$filtered=$this->one('SELECT COUNT(*) total'.$from.$where,$p);$sort=['payment_code'=>'py.payment_code','payment_date'=>'py.payment_date','invoice_code'=>'i.invoice_code','vendor_name'=>'v.name','project_name'=>'p.name','amount'=>'py.amount','payment_method'=>'py.payment_method','status'=>'py.status'];$r=$this->db->execute('SELECT py.id,py.payment_code,py.payment_date,py.amount,py.payment_method,py.status,i.invoice_code,i.invoice_number,v.name vendor_name,p.name project_name'.$from.$where.' ORDER BY '.($sort[$q->sortColumn]??'py.payment_date').' '.$q->sortDirection.',py.id '.$q->sortDirection.' LIMIT ? OFFSET ?',[...$p,$q->length,$q->start]);return['recordsTotal'=>(int)($total['total']??0),'recordsFiltered'=>(int)($filtered['total']??0),'rows'=>$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[]];}}
